using VMLAssembler;

namespace VMLTranslators
{
    /// <summary>
    /// AVR ATmega328P 转译器 (32-bit SRAM 虚拟寄存器)
    /// VML R0-R15 存储在 SRAM (VR_BASE + regNum*4, 4字节/寄存器, 小端序)
    /// </summary>
    public class TranslatorAVR : Translator8bit
    {
        public override string ARCH_NAME => "AVR";
        protected override string CallMnemonic => "CALL";
        protected override string FloatLibLabel(OpCode op) => $"__{op.ToString().ToLower()}";

        // AVR 中断上下文 (__sw_int helper 内部处理上下文保存)
        protected override string[] ContextRegNames() => new string[0];
        protected override string NativeIret() => "reti";
        protected override string NativeCli() => "cli";
        protected override string NativeSti() => "sei";
        protected override void EmitNativeInt(int vector) => Emit("        call __sw_int");

        private const string VR_BASE = "0x0100";
        private string VrAddr(int reg) => $"0x{0x0100 + reg * 4:X4}";

        public TranslatorAVR(VmlProgram vmlProgram) : base(vmlProgram) { }

        protected override void EmitHeader()
        {
            Emit("; AVR ATmega328P Assembly - Translated from VML (32-bit SRAM VR)");
            Emit("; Generated by VML Translator");
            Emit("; Assembler: avra / avr-as");
            Emit("");
            Emit("        .device ATmega328P");
            Emit("        .org 0x0000");
            Emit("");
        }

        protected override void EmitDataSection()
        {
            Emit("");
            Emit("        .dseg");
            Emit("        .org 0x0100");
            Emit("vregs:  .byte 64               ; VML R0-R15 (16 x 4 bytes)");
            if (VmlProgram.DataSection.Count > 0)
            {
                foreach (var kvp in VmlProgram.DataSection)
                {
                    string name = kvp.Key;
                    object value = kvp.Value;
                    if (value is string strValue)
                        Emit($"{name}: .byte {strValue.Length + 1}");
                    else if (value is System.Collections.IList listValue)
                        Emit($"{name}: .byte {listValue.Count}");
                    else if (int.TryParse(value.ToString(), out _))
                        Emit($"{name}: .byte 4");
                }
            }
            Emit("");
        }

        protected override void EmitCode()
        {
            Emit("        .cseg");
            Emit("        .org 0x0000");
            Emit("");
            Emit("; === Reset & Interrupt Vectors ===");
            Emit("        jmp RESET");
            Emit("        jmp INT0_ISR");
            Emit("        jmp INT1_ISR");
            Emit("        jmp PCINT0_ISR");
            Emit("        jmp PCINT1_ISR");
            Emit("        jmp PCINT2_ISR");
            Emit("        jmp WDT_ISR");
            Emit("        jmp TIM2_COMPA_ISR");
            Emit("        jmp TIM2_COMPB_ISR");
            Emit("        jmp TIM1_CAPT_ISR");
            Emit("        jmp TIM1_COMPA_ISR");
            Emit("        jmp TIM1_COMPB_ISR");
            Emit("        jmp TIM1_OVF_ISR");
            Emit("        jmp TIM0_COMPA_ISR");
            Emit("        jmp TIM0_COMPB_ISR");
            Emit("        jmp TIM0_OVF_ISR");
            Emit("        jmp SPI_STC_ISR");
            Emit("        jmp USART_RX_ISR");
            Emit("        jmp USART_UDRE_ISR");
            Emit("        jmp USART_TX_ISR");
            Emit("        jmp ADC_ISR");
            Emit("        jmp EE_READY_ISR");
            Emit("        jmp SPM_READY_ISR");
            Emit("        jmp GSC_ISC");
            Emit("");
            Emit("RESET: ldi r16, high(RAMEND)");
            Emit("       out SPH, r16");
            Emit("       ldi r16, low(RAMEND)");
            Emit("       out SPL, r16");
            Emit("       sei");
            Emit("");
            Emit("; === Main Code ===");
            Emit("        rjmp main");
            Emit("");

            foreach (var instr in VmlProgram.Instructions)
            {
                if (!string.IsNullOrEmpty(instr.Label))
                    Emit($"{instr.Label}:");
                NormalizeAndTranslate(instr);
            }
        }

        // ---- helper: 从虚拟寄存器加载32位到 r18:r19:r20:r21 (low→high) ----
        private void LoadVR(int reg, string comment = "")
        {
            string addr = VrAddr(reg);
            Emit($"        ldi ZL, lo8({addr})       ; {comment}");
            Emit($"        ldi ZH, hi8({addr})");
            Emit("        ld r18, Z+");
            Emit("        ld r19, Z+");
            Emit("        ld r20, Z+");
            Emit("        ld r21, Z");
        }

        // ---- helper: 从 r18:r19:r20:r21 存储32位到虚拟寄存器 ----
        private void StoreVR(int reg, string comment = "")
        {
            string addr = VrAddr(reg);
            Emit($"        ldi ZL, lo8({addr})       ; {comment}");
            Emit($"        ldi ZH, hi8({addr})");
            Emit("        st Z+, r18");
            Emit("        st Z+, r19");
            Emit("        st Z+, r20");
            Emit("        st Z, r21");
        }

        // ---- helper: 从内存地址加载32位到 r18:r19:r20:r21 ----
        private void LoadMem32(string addr)
        {
            Emit($"        ldi ZL, lo8({addr})");
            Emit($"        ldi ZH, hi8({addr})");
            Emit("        ld r18, Z+");
            Emit("        ld r19, Z+");
            Emit("        ld r20, Z+");
            Emit("        ld r21, Z");
        }

        // ---- helper: 从 r18:r19:r20:r21 存储32位到内存地址 ----
        private void StoreMem32(string addr)
        {
            Emit($"        ldi ZL, lo8({addr})");
            Emit($"        ldi ZH, hi8({addr})");
            Emit("        st Z+, r18");
            Emit("        st Z+, r19");
            Emit("        st Z+, r20");
            Emit("        st Z, r21");
        }

        // ---- helper: 加载32位立即数到 r18:r19:r20:r21 ----
        private void LoadImm32(int value)
        {
            Emit($"        ldi r18, lo8({value & 0xFF})");
            Emit($"        ldi r19, lo8({(value >> 8) & 0xFF})");
            Emit($"        ldi r20, lo8({(value >> 16) & 0xFF})");
            Emit($"        ldi r21, lo8({(value >> 24) & 0xFF})");
        }

        // ---- helper: 获取虚拟寄存器操作数的地址表达式 ----
        private string GetVrAddr(Operand op)
        {
            if (op.Type == OperandType.REGISTER)
                return VrAddr((int)op.Value);
            return op.Value.ToString();
        }

        protected override void TranslateInstruction(Instruction instr)
        {
            // NormalizeBinaryOp handled by BaseTranslator.NormalizeAndTranslate
            switch (instr.Opcode)
            {
                // ======== 32位数据传送 ========
                                                case OpCode.MOVE:
                    TranslateMove(instr);
                    break;

                // ======== 32位算术运算 ========
                case OpCode.ADD:
                    TranslateAdd(instr);
                    break;
                case OpCode.SUB:
                    TranslateSub(instr);
                    break;
                case OpCode.MUL:
                    Emit("        call __mulsi3");
                    break;
                case OpCode.DIV:
                    Emit("        call __divsi3");
                    break;
                case OpCode.MOD:
                    Emit("        call __modsi3");
                    break;
                case OpCode.INC:
                    TranslateInc(instr);
                    break;
                case OpCode.DEC:
                    TranslateDec(instr);
                    break;
                case OpCode.NEG:
                    TranslateNeg(instr);
                    break;

                // ======== 32位逻辑运算 ========
                case OpCode.AND:
                    TranslateBitwise(instr, "and");
                    break;
                case OpCode.OR:
                    TranslateBitwise(instr, "or");
                    break;
                case OpCode.XOR:
                    TranslateBitwise(instr, "eor");
                    break;
                case OpCode.NOT:
                    TranslateNot(instr);
                    break;
                case OpCode.SHL:
                    TranslateShift(instr, "lsl");
                    break;
                case OpCode.SHR:
                    TranslateShift(instr, "lsr");
                    break;

                // ======== 比较跳转 ========
                case OpCode.CMP:
                    TranslateCmp(instr);
                    break;
                case OpCode.JMP:
                    Emit($"        rjmp {instr.Operands[0].Value}");
                    break;
                case OpCode.JZ:
                case OpCode.JE:
                    Emit($"        breq {instr.Operands[0].Value}");
                    break;
                case OpCode.JNZ:
                case OpCode.JNE:
                    Emit($"        brne {instr.Operands[0].Value}");
                    break;
                case OpCode.JL:
                    Emit($"        brlt {instr.Operands[0].Value}");
                    break;
                case OpCode.JLE:
                    Emit($"        brle {instr.Operands[0].Value}");
                    break;
                case OpCode.JG:
                    Emit($"        brgt {instr.Operands[0].Value}");
                    break;
                case OpCode.JGE:
                    Emit($"        brge {instr.Operands[0].Value}");
                    break;

                // ======== 控制 ========
                case OpCode.HALT:
                    Emit("        sleep");
                    break;
                case OpCode.NOP:
                    Emit("        nop");
                    break;
                case OpCode.STI:
                // CLI/STI/INT/IRET handled by BaseTranslator.TryTranslateCommonOpcode
                case OpCode.THROW:
                    Emit("        call __throw");
                    break;
                case OpCode.CATCH:
                    break;
                case OpCode.ENDCATCH:
                    break;

                // ======== 栈操作 (32位) ========
                case OpCode.PUSH:
                    Emit("        push r21");
                    Emit("        push r20");
                    Emit("        push r19");
                    Emit("        push r18");
                    break;
                case OpCode.POP:
                    Emit("        pop r18");
                    Emit("        pop r19");
                    Emit("        pop r20");
                    Emit("        pop r21");
                    break;

                // ======== 函数调用 ========
                case OpCode.CALL:
                    Emit($"        call {instr.Operands[0].Value}");
                    break;
                case OpCode.RET:
                    Emit("        ret");
                    break;
                // case OpCode.RET_VAL:
                //     Emit("        ret");
                //     break;
                case OpCode.LABEL:
                    Emit($"{instr.Operands[0].Value}:");
                    break;
                case OpCode.SYSCALL:
                    Emit($"        call __syscall_{instr.Operands[0].Value}");
                    break;

                // ======== 栈帧管理 ========
                case OpCode.ENTER:
                    {
                        int size = int.Parse(instr.Operands[0].Value.ToString());
                        Emit("        push r29");
                        Emit("        push r28");
                        Emit("        in r28, SPL");
                        Emit("        in r29, SPH");
                        if (size > 0)
                        {
                            Emit($"        ldi r16, lo8({size})");
                            Emit($"        ldi r17, hi8({size})");
                            Emit("        sub r28, r16");
                            Emit("        sbc r29, r17");
                            Emit("        out SPL, r28");
                            Emit("        out SPH, r29");
                        }
                    }
                    break;
                case OpCode.LEAVE:
                    Emit("        movw r28, r28");
                    Emit("        out SPL, r28");
                    Emit("        out SPH, r29");
                    Emit("        pop r28");
                    Emit("        pop r29");
                    break;
                case OpCode.CLC:
                    Emit("        clc");
                    break;
                case OpCode.STC:
                    Emit("        sec");
                    break;
                                case OpCode.BREAK:
                    Emit("        break");
                    break;

                // ======== 8/16位数据传输 (与 32 位兼容) ========
                                                                                case OpCode.MOVEB:
                    {
                        var src = instr.Operands[1];
                        if (src.Type == OperandType.REGISTER)
                        {
                            string saddr = VrAddr((int)src.Value);
                            Emit($"        ldi ZL, lo8({saddr})");
                            Emit($"        ldi ZH, hi8({saddr})");
                            Emit("        ld r18, Z");
                        }
                    }
                    break;
                case OpCode.MOVEH:
                    {
                        var src = instr.Operands[1];
                        if (src.Type == OperandType.REGISTER)
                        {
                            string saddr = VrAddr((int)src.Value);
                            Emit($"        ldi ZL, lo8({saddr})");
                            Emit($"        ldi ZH, hi8({saddr})");
                            Emit("        ld r18, Z+");
                            Emit("        ld r19, Z");
                        }
                    }
                    break;
                case OpCode.PUSHB:
                    Emit("        push r18");
                    break;
                case OpCode.PUSHH:
                    Emit("        push r19");
                    Emit("        push r18");
                    break;
                case OpCode.POPB:
                    Emit("        pop r18");
                    break;
                case OpCode.POPH:
                    Emit("        pop r18");
                    Emit("        pop r19");
                    break;

                // ======== 可变移位 ========
                case OpCode.SHLV:
                    Emit("        lsl r18");
                    Emit("        rol r19");
                    Emit("        rol r20");
                    Emit("        rol r21");
                    break;
                case OpCode.SHRV:
                    Emit("        lsr r21");
                    Emit("        ror r20");
                    Emit("        ror r19");
                    Emit("        ror r18");
                    break;
                case OpCode.ZERO:
                    Emit("        clr r18");
                    Emit("        clr r19");
                    Emit("        clr r20");
                    Emit("        clr r21");
                    break;
                case OpCode.TEST:
                    Emit("        mov r0, r18");
                    Emit("        or r0, r19");
                    Emit("        or r0, r20");
                    Emit("        or r0, r21");
                    break;

                // ======== 内联汇编 ========
                // OpCode.CHIPASM handled by BaseTranslator.TryTranslateCommonOpcode

                // ======== 内联汇编 (ASM) ========
                // OpCode.ASM handled by BaseTranslator.TryTranslateCommonOpcode

                // ======== 浮点 ========
                case OpCode.FADD:
                case OpCode.FSUB:
                case OpCode.FMUL:
                case OpCode.FDIV:
                case OpCode.FNEG:
                case OpCode.FCMP:
                case OpCode.I2F:
                case OpCode.F2I:
                case OpCode.F2D:
                case OpCode.D2F:
                case OpCode.MOVEF:
                case OpCode.I2D:
                case OpCode.D2I:
                // 符号扩展/条件移动/循环移位 (v1.66.28+) — 8-bit 架构使用软件库
                case OpCode.SEXTB:
                case OpCode.SEXTH:
                case OpCode.CMOVZ:
                case OpCode.CMOVNZ:
                case OpCode.ROL:
                case OpCode.ROR:
                    Emit($"        call __{instr.Opcode.ToString().ToLower()}");
                    break;
                default:
                    Emit($"        ; UNIMPLEMENTED: {instr.Opcode} {string.Join(", ", instr.Operands)}");
                    break;
            }
        }

        // ======================== LOAD ========================
        private void TranslateLoad(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            if (src.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src);
                LoadImm32(value);
            }
            else if (src.Type == OperandType.MEMORY)
            {
                string addr = src.Value.ToString();
                LoadMem32(addr);
            }
            else if (src.Type == OperandType.REGISTER)
            {
                string saddr = VrAddr((int)src.Value);
                LoadMem32(saddr);
            }

            if (dst.Type == OperandType.REGISTER)
                StoreVR((int)dst.Value);
        }

        // ======================== STORE ========================
        private void TranslateStore(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];
            if (src.Type == OperandType.REGISTER)
            {
                string saddr = VrAddr((int)src.Value);
                LoadMem32(saddr);
            }
            else if (src.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src);
                LoadImm32(value);
            }
            if (dst.Type == OperandType.MEMORY)
            {
                string addr = dst.Value.ToString();
                StoreMem32(addr);
            }
            else if (dst.Type == OperandType.REGISTER)
            {
                StoreVR((int)dst.Value);
            }
        }

        // ======================== MOVE ========================
        private void TranslateMove(Instruction instr)
        {
            // v1.65.167+: 统一 MOVE — MEM/LABEL dest → Store, 其他 → Load
            if (instr.Operands[0].Type == OperandType.MEMORY ||
                instr.Operands[0].Type == OperandType.INDIRECT ||
                instr.Operands[0].Type == OperandType.LABEL)
            {
                TranslateStore(instr);
                return;
            }
            TranslateLoad(instr);
        }

        // ======================== ADD ========================
        private void TranslateAdd(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            LoadVR((int)src1.Value, "ADD src1");

            if (src2.Type == OperandType.REGISTER)
            {
                string addr2 = VrAddr((int)src2.Value);
                Emit($"        ldi ZL, lo8({addr2})    ; ADD src2");
                Emit($"        ldi ZH, hi8({addr2})");
                Emit("        ld r22, Z+");
                Emit("        ld r23, Z+");
                Emit("        ld r24, Z+");
                Emit("        ld r25, Z");
                Emit("        add r18, r22");
                Emit("        adc r19, r23");
                Emit("        adc r20, r24");
                Emit("        adc r21, r25");
            }
            else if (src2.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src2);
                Emit($"        subi r18, {-value & 0xFF}");
                Emit($"        sbci r19, -{(value >> 8) & 0xFF}");
                Emit($"        sbci r20, -{(value >> 16) & 0xFF}");
                Emit($"        sbci r21, -{(value >> 24) & 0xFF}");
            }
            if (dst.Type == OperandType.REGISTER)
                StoreVR((int)dst.Value, "ADD dst");
        }

        // ======================== SUB ========================
        private void TranslateSub(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            LoadVR((int)src1.Value, "SUB src1");

            if (src2.Type == OperandType.REGISTER)
            {
                string addr2 = VrAddr((int)src2.Value);
                Emit($"        ldi ZL, lo8({addr2})    ; SUB src2");
                Emit($"        ldi ZH, hi8({addr2})");
                Emit("        ld r22, Z+");
                Emit("        ld r23, Z+");
                Emit("        ld r24, Z+");
                Emit("        ld r25, Z");
                Emit("        sub r18, r22");
                Emit("        sbc r19, r23");
                Emit("        sbc r20, r24");
                Emit("        sbc r21, r25");
            }
            else if (src2.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src2);
                Emit($"        subi r18, {value & 0xFF}");
                Emit($"        sbci r19, {(value >> 8) & 0xFF}");
                Emit($"        sbci r20, {(value >> 16) & 0xFF}");
                Emit($"        sbci r21, {(value >> 24) & 0xFF}");
            }
            if (dst.Type == OperandType.REGISTER)
                StoreVR((int)dst.Value, "SUB dst");
        }

        // ======================== INC/DEC/NEG ========================
        private void TranslateInc(Instruction instr)
        {
            int reg = (int)instr.Operands[0].Value;
            string addr = VrAddr(reg);
            Emit($"        ldi ZL, lo8({addr})        ; INC R{reg}");
            Emit($"        ldi ZH, hi8({addr})");
            Emit("        ld r18, Z+");
            Emit("        ld r19, Z+");
            Emit("        ld r20, Z+");
            Emit("        ld r21, Z");
            Emit("        subi r18, -1");
            Emit("        sbci r19, -0");
            Emit("        sbci r20, -0");
            Emit("        sbci r21, -0");
            Emit("        ldi ZL, lo8({addr})");
            Emit("        ldi ZH, hi8({addr})");
            Emit("        st Z+, r18");
            Emit("        st Z+, r19");
            Emit("        st Z+, r20");
            Emit("        st Z, r21");
        }

        private void TranslateDec(Instruction instr)
        {
            int reg = (int)instr.Operands[0].Value;
            string addr = VrAddr(reg);
            Emit($"        ldi ZL, lo8({addr})        ; DEC R{reg}");
            Emit($"        ldi ZH, hi8({addr})");
            Emit("        ld r18, Z+");
            Emit("        ld r19, Z+");
            Emit("        ld r20, Z+");
            Emit("        ld r21, Z");
            Emit("        subi r18, 1");
            Emit("        sbci r19, 0");
            Emit("        sbci r20, 0");
            Emit("        sbci r21, 0");
            Emit("        ldi ZL, lo8({addr})");
            Emit("        ldi ZH, hi8({addr})");
            Emit("        st Z+, r18");
            Emit("        st Z+, r19");
            Emit("        st Z+, r20");
            Emit("        st Z, r21");
        }

        private void TranslateNeg(Instruction instr)
        {
            int reg = (int)instr.Operands[0].Value;
            string addr = VrAddr(reg);
            Emit($"        ldi ZL, lo8({addr})        ; NEG R{reg}");
            Emit($"        ldi ZH, hi8({addr})");
            Emit("        ld r18, Z+");
            Emit("        ld r19, Z+");
            Emit("        ld r20, Z+");
            Emit("        ld r21, Z");
            Emit("        com r18");
            Emit("        com r19");
            Emit("        com r20");
            Emit("        com r21");
            Emit("        subi r18, -1");
            Emit("        sbci r19, -0");
            Emit("        sbci r20, -0");
            Emit("        sbci r21, -0");
            Emit("        ldi ZL, lo8({addr})");
            Emit("        ldi ZH, hi8({addr})");
            Emit("        st Z+, r18");
            Emit("        st Z+, r19");
            Emit("        st Z+, r20");
            Emit("        st Z, r21");
        }

        // ======================== 位运算 ========================
        private void TranslateBitwise(Instruction instr, string op)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            LoadVR((int)src1.Value, $"{op} src1");

            if (src2.Type == OperandType.REGISTER)
            {
                string addr2 = VrAddr((int)src2.Value);
                Emit($"        ldi ZL, lo8({addr2})    ; {op} src2");
                Emit($"        ldi ZH, hi8({addr2})");
                Emit("        ld r22, Z+");
                Emit("        ld r23, Z+");
                Emit("        ld r24, Z+");
                Emit("        ld r25, Z");
                Emit($"        {op} r18, r22");
                Emit($"        {op} r19, r23");
                Emit($"        {op} r20, r24");
                Emit($"        {op} r21, r25");
            }
            else if (src2.Type == OperandType.IMMEDIATE)
            {
                int val = SafeToInt(src2);
                if (op == "and")
                {
                    Emit($"        andi r18, {val & 0xFF}");
                    Emit($"        andi r19, {(val >> 8) & 0xFF}");
                    if ((val >> 16) != 0xFF) Emit($"        andi r20, {(val >> 16) & 0xFF}");
                    if ((val >> 24) != 0xFF) Emit($"        andi r21, {(val >> 24) & 0xFF}");
                }
                else if (op == "or")
                {
                    Emit($"        ori r18, {val & 0xFF}");
                    Emit($"        ori r19, {(val >> 8) & 0xFF}");
                    if ((val >> 16) != 0) Emit($"        ori r20, {(val >> 16) & 0xFF}");
                    if ((val >> 24) != 0) Emit($"        ori r21, {(val >> 24) & 0xFF}");
                }
                else
                {
                    Emit($"        ldi r22, {val & 0xFF}");
                    Emit($"        ldi r23, {(val >> 8) & 0xFF}");
                    Emit($"        ldi r24, {(val >> 16) & 0xFF}");
                    Emit($"        ldi r25, {(val >> 24) & 0xFF}");
                    Emit($"        eor r18, r22");
                    Emit($"        eor r19, r23");
                    Emit($"        eor r20, r24");
                    Emit($"        eor r21, r25");
                }
            }
            if (dst.Type == OperandType.REGISTER)
                StoreVR((int)dst.Value, $"{op} dst");
        }

        private void TranslateNot(Instruction instr)
        {
            int reg = (int)instr.Operands[0].Value;
            string addr = VrAddr(reg);
            Emit($"        ldi ZL, lo8({addr})        ; NOT R{reg}");
            Emit($"        ldi ZH, hi8({addr})");
            Emit("        ld r18, Z+");
            Emit("        ld r19, Z+");
            Emit("        ld r20, Z+");
            Emit("        ld r21, Z");
            Emit("        com r18");
            Emit("        com r19");
            Emit("        com r20");
            Emit("        com r21");
            StoreVR(reg, "NOT done");
        }

        private void TranslateShift(Instruction instr, string dir)
        {
            int reg = (int)instr.Operands[0].Value;
            string addr = VrAddr(reg);
            Emit($"        ldi ZL, lo8({addr})        ; SHIFT R{reg}");
            Emit($"        ldi ZH, hi8({addr})");
            Emit("        ld r18, Z+");
            Emit("        ld r19, Z+");
            Emit("        ld r20, Z+");
            Emit("        ld r21, Z");
            if (dir == "lsl")
            {
                Emit("        lsl r18");
                Emit("        rol r19");
                Emit("        rol r20");
                Emit("        rol r21");
            }
            else
            {
                Emit("        lsr r21");
                Emit("        ror r20");
                Emit("        ror r19");
                Emit("        ror r18");
            }
            StoreVR(reg, "SHIFT done");
        }

        // ======================== CMP ========================
        private void TranslateCmp(Instruction instr)
        {
            var src1 = instr.Operands[0];
            var src2 = instr.Operands[1];

            LoadVR((int)src1.Value, "CMP src1");

            if (src2.Type == OperandType.REGISTER)
            {
                string addr2 = VrAddr((int)src2.Value);
                Emit($"        ldi ZL, lo8({addr2})    ; CMP src2");
                Emit($"        ldi ZH, hi8({addr2})");
                Emit("        ld r22, Z+");
                Emit("        ld r23, Z+");
                Emit("        ld r24, Z+");
                Emit("        ld r25, Z");
                Emit("        cp r18, r22");
                Emit("        cpc r19, r23");
                Emit("        cpc r20, r24");
                Emit("        cpc r21, r25");
            }
            else if (src2.Type == OperandType.IMMEDIATE)
            {
                int val = SafeToInt(src2);
                Emit($"        cpi r18, {val & 0xFF}");
                Emit($"        ldi r22, {(val >> 8) & 0xFF}");
                Emit("        cpc r19, r22");
                Emit($"        ldi r22, {(val >> 16) & 0xFF}");
                Emit("        cpc r20, r22");
                Emit($"        ldi r22, {(val >> 24) & 0xFF}");
                Emit("        cpc r21, r22");
            }
        }

        protected override string MapRegister(int regNum)
        {
            return $"r{Math.Min(Math.Max(regNum, 0), 31)}";
        }

        protected override string GetOperandValue(Operand operand)
        {
            switch (operand.Type)
            {
                case OperandType.IMMEDIATE:
                    return $"#{operand.Value}";
                case OperandType.REGISTER:
                    return MapRegister((int)operand.Value);
                case OperandType.MEMORY:
                    return $"[{operand.Value}]";
                default:
                    return operand.Value.ToString();
            }
        }
    }
}
